import { polygonRings } from './kml-polygon.js';

// A Placemark as a feature.
export function featureOf(placemark) {
  const geometry = placemark.polygon ? { type: 'Polygon', rings: polygonRings(placemark.polygon) } : null;
  return { id: placemark.id, properties: placemark.data, geometry };
}

