function ringOf(text) {
  const t = (text ?? '').trim();
  return t ? t.split(/\s+/).map((pair) => pair.split(',').map(Number)) : [];
}

// KML Polygon to rings: the outer boundary, then each inner boundary. Empty inner boundaries are
// left out, and a Polygon whose outer boundary is empty has no rings (null).
export function polygonRings(polygon) {
  const outer = ringOf(polygon.outer);
  if (outer.length === 0) return null;
  return [outer, ...polygon.inner.map(ringOf).filter((ring) => ring.length > 0)];
}

