import { polygonRings } from './kml-polygon.js';

// A Placemark as a feature. A Polygon with no outer boundary gives a feature with no geometry.
export function featureOf(placemark) {
  const rings = placemark.polygon ? polygonRings(placemark.polygon) : null;
  const geometry = rings ? { type: 'Polygon', rings } : null;
  return { id: placemark.id, properties: placemark.data, geometry };
}

