import { test } from 'node:test';
import assert from 'node:assert/strict';
import { featureOf } from '../src/kml-reader.js';
import { openRings } from '../src/validate.js';

const square = '0,0 1,0 1,1 0,1 0,0';

test('an empty inner boundary is left out', () => {
  const feature = featureOf({ id: 1, data: {}, polygon: { outer: square, inner: ['  ', square] } });
  assert.equal(feature.geometry.rings.length, 2);
  assert.deepEqual(openRings([feature]), []);
});

test('a Polygon with an empty outer boundary has no geometry', () => {
  const feature = featureOf({ id: 2, data: { name: 'x' }, polygon: { outer: '', inner: [square] } });
  assert.equal(feature.geometry, null);
  assert.deepEqual(openRings([feature]), []);
});
